const { eventMesh } = require('../../registries/mta')

module.exports = class EventMeshTemplate extends require('../enterprise-messaging') {
  static get kind() { return 'enterprise-messaging-http' }
  static get vcap() { return 'event-mesh-message-client' }

  constructor(...args) {
    super(...args)
    this._name = 'event-mesh'
    this._kind = 'enterprise-messaging-http'
    this._vcap = 'event-mesh-message-client'
    this._dirname = __dirname
    this._mta = eventMesh
  }

  static help() {
    return 'messaging via Event Mesh of SAP Integration Suite'
  }
}
